		// lang: en
		{
			in: in{
				lang: "en",
				cont: VulnInfo{
					CveContents: CveContents{
						Jvn: []CveContent{{
							Type:  Jvn,
							Title: "Title1",
						}},
						RedHat: []CveContent{{
							Type:    RedHat,
							Summary: "Summary RedHat",
